def _fit(df, opts, preset=None, **extra):
    o = pn.normalize_options(dict(BASE, **opts, **extra), preset)
    res = pn.PanelNonlinear(df, o)
    return res, res.fit


def _rel(a, b, floor=1e-3):
    a, b = np.asarray(a, float), np.asarray(b, float)
    return float(np.max(np.abs(a - b) / np.maximum(np.abs(b), floor)))


# ----------------------------------------------------------------------------- estimators vs Stata
@pytest.mark.parametrize("tag", list(CASES))
def test_estimates_match_stata(care, tag):
    opts, preset, tol_b, tol_se = CASES[tag]
    _, fr = _fit(care, opts, preset)
    ref = STATA[tag]
    rb = np.array([v[0] for v in ref["b"]])
    rs = np.array([v[1] for v in ref["b"]])
    assert len(fr.b) == len(rb)
    assert _rel(fr.b, rb) < tol_b
    assert _rel(fr.se, rs, floor=1e-8) < tol_se
    s = ref["s"]
    assert fr.N == int(s["N"])
    if "N_g" in s:
        assert len(fr.Ti) == int(s["N_g"])
    if "ll" in s:
        assert fr.ll == pytest.approx(s["ll"], abs=1e-6)
    if "chi2" in s:
        assert fr.chi2[0] == pytest.approx(s["chi2"], rel=max(tol_se, 1e-6) * 5)
    if "chi2_c" in s:
        assert fr.chi2_lr == pytest.approx(s["chi2_c"], abs=2e-6)
        assert fr.ll_c == pytest.approx(s["ll_c"], abs=1e-7)


def test_derived_parameters_and_display(care):
    res, fr = _fit(care, dict(dep="unmet", family="logit"))
    d = {x["name"]: x for x in fr.derived}
    assert d["sigma_u"]["est"] == pytest.approx(STATA["logit_re"]["s"]["sigma_u"], rel=1e-6)
    assert d["rho"]["est"] == pytest.approx(STATA["logit_re"]["s"]["rho"], rel=1e-6)
    # Stata display: sigma_u 1.049257 (.1160486) [.84477, 1.303243]; rho .2507376 (.0415567) [.1782529, .3404845]
    assert (d["sigma_u"]["se"], d["sigma_u"]["lo"], d["sigma_u"]["hi"]) == pytest.approx((.1160486, .84477, 1.303243), abs=2e-6)
    assert (d["rho"]["se"], d["rho"]["lo"], d["rho"]["hi"]) == pytest.approx((.0415567, .1782529, .3404845), abs=2e-7)
    anc = res.get_table("anc")
    assert [r["param"] for r in anc.rows] == ["/lnsig2u", "sigma_u", "rho"]
    lr = res.get_table("lr_pooled").rows[0]
    assert lr["test"] == "LR test of rho=0" and lr["chi2"] == pytest.approx(57.637594, abs=1e-5)
    # tobit: rho .3919094 (.0291275) [.3361716, .4499619] — CI on the probit scale (diparm ci(probit))
    _, ft = _fit(care, dict(dep="carehrs", family="tobit", ll=0))
    rt = ft.derived[0]
    assert (rt["est"], rt["se"], rt["lo"], rt["hi"]) == pytest.approx((.3919094, .0291275, .3361716, .4499619), abs=2e-7)
    # xtpoisson, re: alpha .3143148 (.0325811) [.256526, .3851219]
    _, fp = _fit(care, dict(dep="visits", family="poisson", exposure="months"))
    a = fp.derived[0]
    assert (a["est"], a["se"], a["lo"], a["hi"]) == pytest.approx((.3143148, .0325811, .256526, .3851219), abs=2e-7)
    # xtnbreg, re: r and s are exp(/ln_r), exp(/ln_s)
    _, fn = _fit(care, dict(dep="visits", family="nbreg", exposure="months"))
    assert [x["name"] for x in fn.derived] == ["r", "s"]
    assert fn.derived[0]["est"] == pytest.approx(np.exp(STATA["nb_re"]["b"][4][0]), rel=1e-6)
    # xtologit: /sigma2_u 1.05031 (.1668506) [.7693019, 1.433963] (log-scale CI)
    ro, fo = _fit(care, dict(dep="sat", family="ologit"))
    row = [r for r in ro.get_table("anc").rows if r["param"] == "/sigma2_u"][0]
    assert (row["est"], row["se"], row["cil"], row["ciu"]) == pytest.approx((1.05031, .1668506, .7693019, 1.433963),
                                                                            abs=2e-6)
    assert [r["param"] for r in ro.get_table("anc").rows] == ["/cut1", "/cut2", "/cut3", "/sigma2_u"]
    # tobit /sigma_u and /sigma_e carry z and p as in Stata
    rtt = _fit(care, dict(dep="carehrs", family="tobit", ll=0))[0].get_table("anc").rows
    assert rtt[0]["param"] == "/sigma_u" and rtt[0]["z"] == pytest.approx(18.17, abs=0.01)


def test_intreg_adaptive_quadrature_and_stata_convergence(care):
    """xtintreg (mvaghermite): Stata 19.5 stops at LL -3161.8197548 (1.7e-5 below the maximum) with the default
    tolerances, and reaches the maximum -3161.8197381467 only with nrtolerance(1e-12) ltolerance(1e-14)
    tolerance(1e-12) (intreg_re_tight); intpoints(30) gives the same early stop, so the quadrature is not the cause.
    Coefficients are compared with the tight run. Stata's /sigma_e SE under mvaghermite (.1551, both runs) is a third of
    the value given by Stata's own intmethod(ghermite) (.4526), by our 12-point adaptive fit and by a brute-force
    Hessian of a 120-point nonadaptive likelihood (.45208) — so the SEs are checked for internal consistency."""
    _, fr = _fit(care, dict(dep="oop_lo", depUpper="oop_hi", family="intreg"))
    tight = STATA["intreg_re_tight"]
    assert _rel(fr.b, [v[0] for v in tight["b"]]) < 1e-6
    assert fr.ll == pytest.approx(tight["s"]["ll"], abs=1e-8)
    assert fr.ll > STATA["intreg_re"]["s"]["ll"] + 1e-5
    _, f60 = _fit(care, dict(dep="oop_lo", depUpper="oop_hi", family="intreg", intMethod="ghermite", intPoints=60))
    assert _rel(fr.b, f60.b) < 1e-6 and _rel(fr.se, f60.se, floor=1e-8) < 1e-5
    assert fr.se[-1] == pytest.approx(0.45208, abs=1e-5)
    assert fr.extra["censor"] == {"n_left": 122, "n_right": 199, "n_point": 187, "n_interval": 1259}


def test_xtpoisson_re_robust_differs_from_stata_by_its_score_convention(care):
    """Stata 19.5 xtpoisson, re vce(robust) (XTPOISSON_FE_ROBUST in xtpoisson.ado) generates the /lnalpha panel score
    on every observation of the panel before _robust sums by panel (T_i times the panel score), applies no M/(M-1)
    factor, and its Wald chi2 includes _cons and /lnalpha. We use the panel score once. Applying Stata's convention to
    our scores reproduces Stata's SEs and chi2 exactly, which locates the difference."""
    _, fr = _fit(care, dict(dep="visits", family="poisson", exposure="months", covType="robust"))
    _, f0 = _fit(care, dict(dep="visits", family="poisson", exposure="months"))
    D = pn.NLData(care, pn.normalize_options(dict(BASE, dep="visits", family="poisson", exposure="months")))
    Z = np.column_stack([D.X, np.ones(D.N)])
    sc = pn.PoissonGammaRE(D.y, Z, D.off, D.Ti).scores(f0.b)
    ours = f0.V @ (sc.T @ sc) @ f0.V
    assert np.allclose(fr.V, ours, rtol=1e-10)
    sc[:, -1] *= D.Ti
    stata_conv = f0.V @ (sc.T @ sc) @ f0.V
    ref = STATA["pois_re_rob"]
    assert _rel(np.sqrt(np.diag(stata_conv)), [v[1] for v in ref["b"]], floor=1e-8) < 1e-6
    assert float(f0.b @ np.linalg.solve(stata_conv, f0.b)) == pytest.approx(ref["s"]["chi2"], rel=1e-5)
    assert any("T_i" in n for n in fr.notes)


def test_dropped_groups_and_omitted_variables(care):
    res, fr = _fit(care, dict(dep="unmet", family="logit", model="fe"))
    assert STATA["logit_fe"]["s"]["N_group_drop"] == 188 and STATA["logit_fe"]["s"]["N_drop"] == 608
    assert fr.extra["n_drop_g"] == 188 and fr.extra["n_drop_o"] == 608
    notes = " ".join(res.get_table("summary").notes + res.get_table("coef").notes)
    assert "188개 집단(608개 관측치)" in notes and "female" in notes and "no within-group variance" in notes
    assert fr.ll_0 == pytest.approx(STATA["logit_fe"]["s"]["ll_0"], abs=1e-8)
    # xtpoisson, fe / xtnbreg, fe: 47 single-observation groups (47 obs), 16 all-zero groups (39 obs) as in the log
    for fam in ("poisson", "nbreg"):
        r, f = _fit(care, dict(dep="visits", family=fam, model="fe", exposure="months"))
        txt = " ".join(r.get_table("summary").notes)
        assert "47개 집단(47개 관측치)" in txt and "16개 집단(39개 관측치)" in txt
    assert "female" in " ".join(_fit(care, dict(dep="visits", family="poisson", model="fe"))[0].get_table("coef").notes)
    assert _fit(care, dict(dep="visits", family="nbreg", model="fe"))[1].names == ["adl", "alone", "female", "_cons"]
