def test_session_aliases_after_xtset(care):
    sess = ost.Session(care.copy())
    sess.xtset("pid", "wave")
    r = sess.run("xtlogit", dep="unmet", covs=X3, model="fe", hausman=False)
    assert r.name == "panelNonlinear" and r.options["family"] == "logit" and r.options["entity"] == "pid"
    assert r.fit.b[0] == pytest.approx(STATA["logit_fe"]["b"][0][0], rel=1e-7)
    r = sess.run("clogit", dep="unmet", covs=X3, group="pid", hausman=False)
