    r = sess.run("xtpoisson", dep="visits", covs=X3, exposure="months", hausman=False)
    assert r.options["reDist"] == "gamma" and r.fit.b[0] == pytest.approx(STATA["pois_re"]["b"][0][0], rel=1e-6)
    r = sess.run("xtoprobit", dep="sat", covs=X3)
