    r = sess.run("xtlogit", dep="unmet", covs=X3, exposure="months", depUpper="oop_hi", ll=0, hausman=False,
                 margins=False)
    assert r.options["exposure"] is None and r.options["ll"] is None and len(r.options["ignored"]) == 2
    assert r.fit.b[0] == pytest.approx(STATA["logit_re"]["b"][0][0], rel=1e-6)
    with pytest.raises(ValueError, match="한 값만"):
        pn.NLData(care.assign(z=1), pn.normalize_options(dict(BASE, dep="z", family="logit")))
    with pytest.raises(ValueError, match="개체 변수"):
        ost.Session(care.copy()).run("xtlogit", dep="unmet", covs=X3)


