# ----------------------------------------------------------------------------- transpile, export, registration
def test_transpile_rules():
    t = pn.transpile("xtlogit unmet adl alone female, fe")
    assert "family='logit'" in t and "model='fe'" in t and "panel_spec" in t
    t = pn.transpile("xtlogit unmet adl alone female, re or intmethod(ghermite) intpoints(20) vce(cluster region) nolog")
    assert all(s in t for s in ("eform=True", "intMethod='ghermite'", "intPoints=20", "covType='cluster'",
                                "clusterVar='region'", "# [Stata] nolog"))
    assert "paCorr='ar1'" in pn.transpile("xtlogit y x, pa corr(ar 1) force vce(robust)")
    t = pn.transpile("clogit unmet adl alone, group(pid) or vce(robust)")
    assert "entity='pid'" in t and "clogit=True" in t and "covType='robust'" in t
    assert "reDist='normal'" in pn.transpile("xtpoisson visits adl, re normal e(months) intm(gh) intp(8)")
    assert "exposure='months'" in pn.transpile("xtnbreg visits adl, fe exposure(months)")
    t = pn.transpile("xttobit carehrs adl, ll(0) ul(15)")
    assert "ll=0.0" in t and "ul=15.0" in t
    assert "ll=True" in pn.transpile("xttobit carehrs adl, ll")
    assert "depUpper='oop_hi'" in pn.transpile("xtintreg oop_lo oop_hi adl alone")
    assert "family='ologit'" in pn.transpile("xtologit sat adl, or vce(robust)")
    for bad in ("xtlogit y x, fe vce(robust)", "xtprobit y x, fe", "xtnbreg y x, re vce(robust)",
                "xttobit y x, ll(0) vce(robust)", "xttobit y x", "clogit y x", "xtlogit y i.g x", "xtlogit y x if t>2",
                "xtlogit y x [iw=w]", "xtlogit y x, re intmethod(aghermite)", "xtlogit y x, re lrmodel",
                "xtlogit y x, re vce(bootstrap)", "xtlogit y x, pa corr(stationary 2)", "xtpoisson y x, fe intpoints(20)",
                "xtlogit y x, exposure(m)", "xtprobit y x, re or", "xtlogit y x, re corr(ar 1)",
                "xtnbreg y x, re intpoints(8)", "xtpoisson y x, fe normal"):
        out = pn.transpile(bad)
        assert out.startswith("raise NotImplementedError("), bad
        assert re.search("[가-힣]", out), bad
    assert pn.transpile("xtreg y x, fe") is None and pn.transpile("logit y x") is None
    for line in ("xtlogit unmet adl, re", "clogit unmet adl, group(pid)", "xtintreg a b x"):
        compile(pn.transpile(line), "<transpiled>", "exec")


